# -*- coding: utf-8 -*-
"""FORT: strength, support, exertion and compulsion; forty excluded."""
import json
from pathlib import Path
from lesson_authoring import entry as E
BASE=Path(__file__).resolve().parents[1];OUT=BASE/'.cache/batch200/drafts/rewrite_spec'
H=[['拉丁 fortis','强壮、坚固、勇敢；更早来源有不同分析']]
F=H+[['后期／通俗拉丁 fortia → 古法语 force','由 fortis 的中性复数名词化，表示力量'],['中古英语 force → 英语 force〔名词〕','力量、强制力；队伍、作用力']]
FV=H+[['后期拉丁 fortia／*fortiāre → 古法语 forcer / forcier','力量 → 用力、强迫；带星号形式为重建'],['中古英语 forcen → 英语 force〔动词〕','迫使、强行推动']]
FT=H+[['古法语 fort → 中古英语 fort → 英语 fort','强的 → 坚固据点、堡垒']]
FY=H+[['晚期拉丁 fortificāre → 古法语 fortifier → 中古英语 fortifien','fortis + facere 的构词形式：使变强'],['现代英语 fortify','加固；增强；强化食品或酒']]
CO=H+[['晚期拉丁 con- + fortis → confortāre','使更有力量；con- 常作加强语气理解'],['古法语 conforter〔动词〕／confort〔名词〕→ 中古英语','给予支持、安慰；安慰、宽慰'],['现代英语 comfort','安慰；舒适、安心；n 后来变为 m']]
CA=CO[:2]+[['古法语／盎格鲁法语 confortable → 中古英语 comfortable','给予安慰、令人愉悦的'],['现代英语 comfortable','舒适的；自在的；宽裕的']]
EF=H+[['通俗拉丁 *exfortiāre → 古法语 esforcier / esforz','表现出力量 → 使劲、努力及其名词；拉丁形式为重建'],['法语 effort → 英语 effort','投入的努力；一次尝试']]
EN=H+[['晚期拉丁 infortiāre → 古法语 enforcier','使强、加固、施力'],['中古英语 enforcen → 英语 enforce','借法语，亦有 en- + force 的本土构词分析；后来专指强制落实']]
RE=EN+[['英语 re- + inforce〔enforce 旧变体〕→ reinforce','再加力量 → 加强、增援']]
W=[
E('force','英 /fɔːs/；美 /fɔːrs/','力；强制力；队伍；迫使、强行推动；瀑布〔另源地域用法〕','力量施加到人或物上，能推、拉，也能逼出某种结果。','力量名词经法语 force 接拉丁 fortis；动词经法语 forcer / forcier 独立传入。英国北部地名里的 Force“瀑布”接古诺斯语 fors，是另一来源。',F+[['并列动词路线：古法语 forcer → 中古英语 forcen → force','施力、迫使'],['另源：古诺斯语 fors → 地域英语 force','瀑布；不从“强壮”的拉丁词推出']],'物理 force 是有大小和方向的力；日常 by force 是靠强力或强迫。police force 指一支警察队伍。force someone to do something 是迫使某人做事，不一定指直接动手。旧“填塞”用法还受到 farce“填馅”影响，与常用义分开看。','by force；force someone to do；a police force；the force of an argument。','power 常说能力、权力或物理功率；force 更强调实际施加的力。High Force 等地名里的 Force 是瀑布，不能按词族硬解释。',('Do not force the lid; turn it gently first.','别硬撬盖子，先轻轻转动它。'),('Heavy snow forced the school to close for the day.','大雪迫使学校当天停课。'),('The diagram shows the forces acting on the box.','图中显示了作用在箱子上的各个力。'),sources=['https://www.etymonline.com/word/force','https://en.wiktionary.org/wiki/force#English']),
E('fort','英 /fɔːt/；美 /fɔːrt/','堡垒；军事据点','把一个地方修得坚固，让里面的人能防守。','借法语 fort，原是“强、坚固”的形容词作名词，接拉丁 fortis；没有隐藏的“第四”或“四十”数词成分。',FT,'可指有防御设施的堡垒，也可指名称保留下来的军营、据点。孩子用毯子搭的“秘密堡垒”也能叫 fort。hold the fort 比喻在别人不在时照看局面。','an old fort；build a fort；hold the fort。','fortress 常更突出规模与坚固防御；fort 范围较宽。castle 还常涉及领主居住的城堡功能。',('The old fort overlooks the river crossing.','旧堡垒俯瞰着过河的渡口。'),('The children built a fort from chairs and blankets.','孩子们用椅子和毯子搭了一座小堡垒。'),sources=['https://www.etymonline.com/word/fort','https://en.wiktionary.org/wiki/fort#English']),
E('fortress','英 /ˈfɔːtrəs/；美 /ˈfɔːrtrəs/','要塞；坚固堡垒','一处被修成很难攻进去的防守地点。','中世纪拉丁 fortalitia 经古法语 forteresce 等形式进入英语，接 fortis；词尾 -ess 在这里不是表示女性的后缀。',H+[['中世纪拉丁 fortalitia → 古法语 forteresce / forteresse','坚固、防御工事 → 要塞'],['中古英语／现代英语 fortress','坚固的防御地点；也可比喻难以突破的环境']],'常让人想到高墙、严密防守的城堡或据点。比喻 a fortress of secrecy 是秘密层层守住，不容易探入。国际象棋也借它说弱方能守住、不让对方突破的布局。','a mountain fortress；an ancient fortress；an impregnable fortress。','fortress 与 fort 同族，但不是 fort 的女性形式。强固程度是意象，不要求每个 fortress 都严格大于每个 fort。',('The fortress was built on a narrow ridge.','要塞建在一道狭窄的山脊上。'),('The office had become a fortress of locked doors and security checks.','办公室变得像座堡垒，到处是锁着的门和安检。'),sources=['https://en.wiktionary.org/wiki/fortress#English','https://www.etymonline.com/word/fortress']),
E('forte','英 /ˈfɔːteɪ/；美 /ˈfɔːrteɪ/；长项义也读英 /fɔːt/、美 /fɔːrt/','长处、拿手项；强、强奏〔音乐〕','在人身上是最强的一项；在乐谱上是要奏得有力量、响一些。','长项义经法语 fort“剑身强部”等义借入，后受意大利语影响加 e；音乐义另借意大利 forte“强”，两线都接拉丁 fortis。',H+[['法语 fort → 英语 fort / forte〔长项〕','剑身靠剑柄的强部 → 人的强项'],['并列：意大利 forte → 英语 forte〔音乐〕','强 → 强奏；常用符号 f']],'Public speaking is her forte 是说演讲是她的强项。音乐指示 forte 要求较强力度，不是更快；常见双音节 /ˈfɔːteɪ/ 已广泛使用，不应简单判成错误。','something is someone’s forte；play forte；a forte passage。','fortitude 是迎难承受的坚毅；forte 是拿手项。音乐里的 piano 表示弱，与 forte 对照。',('Explaining difficult ideas is her forte.','把难懂的想法解释清楚是她的长项。'),('Play the final phrase forte, but keep the tempo steady.','最后一句用强力度演奏，但速度保持稳定。'),sources=['https://www.etymonline.com/word/forte','https://en.wiktionary.org/wiki/forte#English']),
E('fortitude','英 /ˈfɔːtɪtjuːd/；美 /ˈfɔːrtɪtuːd/','坚毅；面对困难的勇气与忍耐','压力压下来，心里仍能撑住，不轻易垮掉。','拉丁 fortitūdō“力量、勇气”由 fortis 加性质名词词尾形成，经法语进入英语；不是 fort + attitude 的混合。',H+[['拉丁 fortitūdō → 古法语 fortitude → 中古英语／英语 fortitude','强大、勇敢 → 承受逆境的精神力量']],'现代多指承受痛苦、挫折或长期压力的精神韧劲，语气庄重。它不只表示冲上去的一刻勇敢，也包括漫长等待中仍然稳得住。','show fortitude；with great fortitude；mental fortitude。','courage 可强调面对危险采取行动；fortitude 更突出在困境中坚持承受。',('She faced the long recovery with remarkable fortitude.','她以非凡的坚毅面对漫长的恢复过程。'),('Finishing the project after so many setbacks required fortitude.','经历这么多挫折后仍完成项目，需要坚忍的意志。'),sources=['https://en.wiktionary.org/wiki/fortitude#English','https://www.etymonline.com/word/fortitude']),
E('fortify','英 /ˈfɔːtɪfaɪ/；美 /ˈfɔːrtəfaɪ/','加固；增强；强化营养；提高酒精度','给原来的东西再加一层力量，让它更能抵挡或支撑。','晚期拉丁 fortificāre 由 fortis“强”与 facere“做、使”的构词形式组成，经古法语进入英语。',FY,'城墙可以 fortify，信心也可以被支持 fortify。食品 fortify with iron 是添加铁等营养成分；fortify wine 则是加入蒸馏酒提高酒精度，不能按“更健康”去理解。','fortify a town；fortify someone’s resolve；fortify food with vitamins。','reinforce 常突出再加支撑；fortify 常带增强防御或使更有力量的意味。食品强化和酒的加强是不同具体过程。',('The defenders fortified the gate with heavy beams.','防守者用粗重梁木加固了大门。'),('The cereal is fortified with iron and several vitamins.','这种早餐谷物添加了铁和几种维生素。'),sources=['https://www.etymonline.com/word/fortify','https://en.wiktionary.org/wiki/fortify#English']),
E('fortifying','英 /ˈfɔːtɪfaɪɪŋ/；美 /ˈfɔːrtəfaɪɪŋ/','加固、强化〔过程〕；使人振作的','正在补上力量，或者让疲倦、动摇的人重新撑起来。','英语 fortify + -ing；可以作进行形式、动名词，也可以作描述作用的形容词。',FY+[['英语 fortify + -ing → fortifying','强化的过程；带来力量或振作感的']],'fortifying the wall 是正在加固墙；a fortifying meal 是让人恢复力气的一餐。后一种用法讲总体感受，不自动表示食物按技术标准添加了营养素。','a fortifying meal；a fortifying thought；fortifying the defences。','fortified food 通常指经过营养强化的食品；a fortifying meal 多说吃后觉得有力气，不必是同一件事。',('A hot meal was fortifying after the long walk.','长途步行后，一顿热饭让人恢复了力气。'),('They spent the afternoon fortifying the riverbank with sandbags.','他们花了一下午用沙袋加固河岸。'),sources=['https://en.wiktionary.org/wiki/fortifying#English','https://www.etymonline.com/word/fortify']),
E('effort','英 /ˈefət/；美 /ˈefərt/','努力；力气；尝试','把自己的力气、时间和注意力拿出来，推动一件事往前走。','经法语 effort 接古法语 esforz、esforcier；通常追到重建的通俗拉丁 *exfortiāre“表现力量”，ex- + fortis。',EF,'put effort into 是投入努力；make an effort 是认真尝试。复数 efforts 常说一系列行动，a first effort 也能指第一次做出的作品。花了 effort 不保证成功，它说的是投入。','make an effort；put effort into；a joint effort；with little effort。','effect 是效果；effort 是努力。effort 的后半通常弱读，不照拼写读成强重音的 fort。',('She put a lot of effort into making the instructions clear.','她花了很多心力把说明写清楚。'),('Their first effort at baking bread was surprisingly good.','他们第一次尝试烤面包，效果出奇地好。'),sources=['https://www.etymonline.com/word/effort','https://en.wiktionary.org/wiki/effort#English']),
E('effortless','英 /ˈefətləs/；美 /ˈefərtləs/','不费力的；看起来轻松的','动作流畅得好像不用费劲，或事情本来就很容易完成。','英语 effort + -less，“没有努力负担”；现代也常描述表面看不出用力。',EF+[['英语 effort + -less → effortless','无需费力，或显得毫不费力']],'a dancer’s effortless movement 常是在赞熟练，背后可能有多年训练。不要因此推断她没有努力学习。产品说 effortless setup，则常想表达安装过程简单省事。','effortless grace；an effortless performance；make something look effortless。','easy 说难度低；effortless 还可强调做起来流畅、看不到用力痕迹。',('Years of practice made her movements look effortless.','多年的练习让她的动作显得毫不费力。'),('The new handle makes opening the heavy drawer almost effortless.','新把手让拉开沉重抽屉几乎不费力。'),sources=['https://www.etymonline.com/word/effortless','https://en.wiktionary.org/wiki/effortless#English']),
E('effortlessly','英 /ˈefətləsli/；美 /ˈefərtləsli/','毫不费力地；轻松自如地','事情做出来很顺，看不出卡顿或吃力。','英语 effortless + -ly。',EF+[['英语 effortless + -ly → effortlessly','以轻松流畅的方式']],'常修饰移动、转换语言、演奏等动作。它描述当下的表现，不负责交代为了做到这一点曾经付出了多少训练。','move effortlessly；switch effortlessly；glide effortlessly。','carelessly 是粗心地，effortlessly 是轻松地。轻松不等于随便，也不等于没有准备。',('She switched effortlessly between the two languages.','她在两种语言之间切换自如。'),('The boat glided effortlessly across the calm lake.','小船轻快地滑过平静的湖面。'),sources=['https://en.wiktionary.org/wiki/effortlessly#English']),
E('comfort','英 /ˈkʌmfət/；美 /ˈkʌmfərt/','安慰；舒适；安心；使宽慰','有人或某种环境把你接住，让身心不再那么难受。','晚期拉丁 confortāre 原来偏“使更有力量”；经法语 conforter 和名词 confort 分别传入英语，逐渐侧重安慰与舒适。',CO,'comfort a friend 是安慰朋友；sit in comfort 是坐得舒服；take comfort in something 是从某件事得到宽慰。由“给人力量”走到“让人安心”，比硬记“舒服”更能连起这些用法。','comfort someone；take comfort in；a source of comfort；in comfort。','comfort 可照顾身体感受，也可缓解情绪；console 通常更集中在失落、悲伤后的安慰。',('Her friend’s quiet presence gave her comfort.','朋友安静地陪着，让她得到安慰。'),('The wider seats allow passengers to travel in comfort.','更宽的座椅让乘客旅途中坐得舒服。'),('He tried to comfort the frightened child.','他试着安慰受到惊吓的孩子。'),sources=['https://www.etymonline.com/word/comfort','https://en.wiktionary.org/wiki/comfort#English']),
E('comfortable','英 /ˈkʌmftəbəl/；美 /ˈkʌmftərbəl/；也有较完整的 /ˈkʌmfətəbəl/、/ˈkʌmfərtəbəl/','舒适的；自在的；宽裕的','身体不用忍受难受，心里也不用一直绷着。','经法语 confortable 接 conforter“安慰、增强”；现代可对照 comfort + -able，历史上是借入的形容词。',CA,'a comfortable chair 让身体舒服；comfortable speaking in public 是讲话时自在；a comfortable income 则是收入足以过得宽裕。be comfortable with a plan 还可说对方案没有不安、可以接受。','comfortable with；comfortable doing；make yourself comfortable。','comforting 是能给人安慰的；comfortable 是舒服自在的。一个硬椅子旁的朋友可能 comforting，椅子却不 comfortable。',('This chair is comfortable even after an hour of reading.','读了一个小时书，坐在这张椅子上仍然舒服。'),('She feels comfortable asking questions in this class.','在这门课上，她很自在，愿意提问。'),sources=['https://www.etymonline.com/word/comfortable','https://en.wiktionary.org/wiki/comfortable#English']),
E('uncomfortable','英 /ʌnˈkʌmftəbəl/；美 /ʌnˈkʌmftərbəl/','不舒服的；不自在的；令人尴尬的','身体有不适，或心里感觉不对劲、放松不下来。','英语 un- + comfortable，否定的是舒适或自在的状态。',CA+[['英语 un- + comfortable → uncomfortable','不舒适；心里不安或尴尬']],'硬座椅让人 uncomfortable，敏感问题也让人 uncomfortable。I’m uncomfortable with this plan 常是委婉说对方案有顾虑，不只是坐姿不舒服。','uncomfortable with；an uncomfortable silence；feel uncomfortable。','uncomforting 是不能给人安慰；uncomfortable 更常说不适、不自在。尴尬感不一定意味着生理疼痛。',('The narrow bench became uncomfortable after a few minutes.','坐了几分钟，狭窄的长凳就让人不舒服了。'),('I felt uncomfortable sharing someone else’s private story.','分享别人的私事让我感到不自在。'),sources=['https://en.wiktionary.org/wiki/uncomfortable#English','https://www.etymonline.com/word/uncomfortable']),
E('comfortably','英 /ˈkʌmftəbli/；美 /ˈkʌmftərbli/','舒服地；轻松地；绰绰有余地','状态宽松、不吃力，或比所需程度高出一截。','英语 comfortable + -ly，词尾 -able 转为 -ably。',CA+[['英语 comfortable + -ly → comfortably','在舒适状态下；以充足余量']],'sit comfortably 是坐得舒服；win comfortably 是赢得轻松；comfortably above the minimum 是明显高于最低要求。后两者把“不紧张、不勉强”延伸到差距。','sit comfortably；comfortably ahead；comfortably afford。','comfortably 不只描述身体感觉。comfortably ahead 说领先幅度充足，不是“舒服地走在前面”。',('The room can comfortably seat twelve people.','这个房间坐十二个人很宽松。'),('She finished comfortably ahead of the other runners.','她以明显优势跑在其他选手前面到达终点。'),sources=['https://en.wiktionary.org/wiki/comfortably#English','https://www.etymonline.com/word/comfortably']),
E('discomfort','英 /dɪsˈkʌmfət/；美 /dɪsˈkʌmfərt/','不适；不安；使不舒服','舒服、安定的感觉被打破，身体或心里开始别扭。','名词经古法语 desconfort，动词经 desconforter 传入；des- + conforter。现代可对照 dis- + comfort，不能把所有历史节点都排在现代 comfort 后。',CO[:2]+[['古法语 des- + conforter → desconforter / desconfort','使失去支持或勇气；不幸、忧伤'],['中古英语／现代英语 discomfort','后来转为身体不适、心理不安；也作动词']],'它常比 pain 温和，可以是鞋挤脚，也可以是社交场合的别扭。正式语境也用作动词 make uncomfortable，但日常名词更常见。','cause discomfort；physical discomfort；a sense of discomfort。','discomfit 是使窘迫、使难堪，远源走 facere“做”，不与 discomfort 直接同源，虽然后来意义接近。',('The tight collar caused some discomfort.','紧衣领让人有些不舒服。'),('His joke created a noticeable sense of discomfort in the room.','他的玩笑让屋里的人明显感到不自在。'),sources=['https://www.etymonline.com/word/discomfort','https://en.wiktionary.org/wiki/discomfort#English']),
E('comforting','英 /ˈkʌmfətɪŋ/；美 /ˈkʌmfərtɪŋ/','令人宽慰的；能给人安慰的','不一定解决了问题，却让人觉得没那么孤单、慌张。','英语 comfort + -ing，由动作转为描述其带来的作用。',CO+[['英语 comfort + -ing → comforting','正在安慰；让人得到宽慰的']],'comforting words 是让人安心的话，a comforting thought 是能带来安慰的想法。It is comforting to know... 常用来说明哪条消息让自己心里安定下来。','comforting words；a comforting thought；find something comforting。','comfortable 描述舒服自在；comforting 描述能使别人感到宽慰的作用。',('It was comforting to know that someone was waiting at home.','知道家里有人在等，令人安心。'),('She placed a comforting hand on his shoulder.','她把手搭在他肩上，安慰着他。'),sources=['https://en.wiktionary.org/wiki/comforting#English','https://www.etymonline.com/word/comfort']),
E('forceful','英 /ˈfɔːsfəl/；美 /ˈfɔːrsfəl/','有力的；坚定有说服力的','表现出足够力量，让人感到它的分量。','英语 force + -ful，表示充满力量或力度。',F+[['英语 force + -ful → forceful','有力的；表达坚定、鲜明的']],'a forceful argument 是论证有力，不是把别人按住才算。forceful personality 则说人坚定、能推动局面；语气可褒可贬，要看是否压过别人。','a forceful argument；a forceful response；a forceful speaker。','forcible 常指靠武力或强制完成；forceful 更多评价表达或动作的力度。',('She gave a forceful explanation of why the plan would fail.','她有力地解释了这个计划为什么行不通。'),('A forceful push opened the jammed door.','用力一推，卡住的门开了。'),sources=['https://en.wiktionary.org/wiki/forceful#English','https://www.etymonline.com/word/forceful']),
E('forcible','英 /ˈfɔːsəbəl/；美 /ˈfɔːrsəbəl/','强制的；使用强力的','不是对方自愿配合，而是靠力量迫使事情发生。','借古法语 forcible，接 forcier“用强力迫使”；现代可对照 force + -ible，但不能机械理解为“能够被强迫的”。',H+[['古法语 force → forcier → forcible','力量 → 施力 → 以强力完成的'],['中古英语／现代英语 forcible','强制的；使用武力的']],'forcible entry 是强行进入，forcible removal 是强制移走。现代常描述动作实施的方式，不只是说某人说话特别有气势。','forcible entry；forcible removal；forcible displacement。','forceful speech 是有力的讲话；forcible action 是靠强力实施的行动。两者不能只因都含 force 就互换。',('There were signs of forcible entry around the lock.','锁周围有强行进入的痕迹。'),('The report describes the forcible removal of residents.','报告描述了居民被强制迁离的情况。'),sources=['https://www.etymonline.com/word/forcible','https://en.wiktionary.org/wiki/forcible#English']),
E('forcibly','英 /ˈfɔːsəbli/；美 /ˈfɔːrsəbli/','强行地；有力地','通过强力使事情发生；有时也说某种感受被强烈地唤起。','接 forcible + -ly，-ible 变 -ibly；中古英语已有相应副词形式 forceably。',H+[['古法语 forcible → 中古英语 forcible / forceably','强力的及其英语副词'],['现代英语 forcibly','用强力地；强烈地']],'forcibly removed 是被强行移走。be forcibly reminded of something 则是某种相似情况让人强烈想起往事，未必有人真的用身体强迫。','forcibly remove；forcibly restrain；be forcibly reminded。','forcefully 更常说表达有力度；forcibly 更常说强制执行或遭遇强烈提醒。',('The locked gate had been forcibly opened.','锁着的大门被强行打开了。'),('The empty house forcibly reminded her of how much had changed.','空荡荡的房子强烈地提醒她，一切已经改变了许多。'),sources=['https://en.wiktionary.org/wiki/forcibly#English','https://www.etymonline.com/word/forcible']),
E('enforce','英 /ɪnˈfɔːs/；美 /ɪnˈfɔːrs/','执行、落实〔规则等〕；强制实行','规则不只写在纸上，还要让人真正照着做。','古法语 enforcier 经中古英语传入，远接拉丁 fortis；也有英语 en- + force 的构词分析。早义包括加强、施力，后转向强制遵守。',EN,'enforce a rule 是用检查、限制或处罚等手段确保规则被遵守。它不是制定规则：一个人可以写规则，另一个人负责执行。','enforce a rule；enforce a ban；strictly enforced。','obey 是自己遵守；enforce 是使规则得到遵守。implement 更广，既可实施政策也可实现技术方案。',('The staff enforce the rule that food must stay outside the laboratory.','工作人员执行实验室内不得带入食物的规定。'),('A rule is ineffective if nobody enforces it.','如果没人执行，规定就不起作用。'),sources=['https://www.etymonline.com/word/enforce','https://en.wiktionary.org/wiki/enforce#English']),
E('enforcement','英 /ɪnˈfɔːsmənt/；美 /ɪnˈfɔːrsmənt/','执行；强制落实；执法','把规则从要求变成实际约束的过程。','古法语 enforcement 接 enforcier，借入英语；现代可拆 enforce + -ment，但名词有独立法语来源。',EN[:-1]+[['古法语 enforcier → enforcement → 英语 enforcement','加强、强迫 → 规则的强制实施']],'law enforcement 是执法；enforcement of parking rules 是落实停车规则。它关注确保遵守的行为，和规则本身是否写得清楚是两个问题。','law enforcement；strict enforcement；enforcement of regulations。','legislation 常说立法或法律条文；enforcement 是执行。制定了条文不等于落实工作已经完成。',('Consistent enforcement helped everyone understand the parking rules.','一贯地执行规定，帮助大家明白了停车规则。'),('The policy explains who is responsible for enforcement.','这份政策说明了谁负责执行。'),sources=['https://www.etymonline.com/word/enforcement','https://en.wiktionary.org/wiki/enforcement#English']),
E('reinforce','英 /ˌriːɪnˈfɔːs/；美 /ˌriːɪnˈfɔːrs/','加强；加固；增援；强化','在已有基础上再添支撑，让它更稳、更有力。','英语 re- + inforce，inforce 是 enforce 的旧变体，当时还表示加强。不是英语 rein“缰绳”+ force。',RE,'可以用梁加固屋顶，也可以用证据加强论点。repeat information to reinforce learning 是帮助巩固学习；reinforce a belief 也可能让错误想法更牢固，词本身不保证内容正确。','reinforce a structure；reinforce a message；reinforce an impression。','enforce 现在主要说落实规则；reinforce 主要说加强某物，通常不只是“再执行一次”。',('Steel bars reinforce the concrete beam.','钢筋增强了混凝土梁的强度。'),('The new evidence reinforced her confidence in the explanation.','新证据增强了她对这一解释的信心。'),sources=['https://www.etymonline.com/word/reinforce','https://en.wiktionary.org/wiki/reinforce#English']),
E('reinforcement','英 /ˌriːɪnˈfɔːsmənt/；美 /ˌriːɪnˈfɔːrsmənt/','加固；加强；强化；增援人员〔常用复数〕','额外加进来的力量，或加上这种力量的过程。','英语 reinforce + -ment；也与较早的 re- + enforcement 构词相联系。',RE+[['英语 reinforce + -ment → reinforcement','加强过程；增加的支撑或人手']],'建筑中的 reinforcement 是加固材料或措施；reinforcements 常指增援人员。心理学的 reinforcement 是使某种行为更可能再次发生的后果；positive 与 negative 在这里指增加或移除刺激，不等于奖励与惩罚的简单二分。','steel reinforcement；send reinforcements；positive reinforcement。','punishment 以减少行为为定义；reinforcement 以增加行为为定义。日常“加强”则不必进入这套专业分类。',('The bridge needs additional reinforcement near its supports.','桥梁在支座附近需要进一步加固。'),('The exhausted rescue team asked for reinforcements.','疲惫的救援队请求增派人手。'),sources=['https://en.wiktionary.org/wiki/reinforcement#English','https://www.etymonline.com/word/reinforcement','https://dictionary.apa.org/reinforcement','https://dictionary.apa.org/negative-reinforcement']),
E('fortification','英 /ˌfɔːtɪfɪˈkeɪʃən/；美 /ˌfɔːrtəfəˈkeɪʃən/','加固；防御工事；营养强化','把防御能力或某项有用成分补上去的过程与成果。','晚期拉丁 fortificātiō 经法语 fortification 借入，接 fortificāre；现代与 fortify 的名词形式对应，但历史上名词独立借入。',H+[['晚期拉丁 fortificāre → fortificātiō → 古法语 fortification','使变强 → 加强、防御工事'],['英语 fortification','加固过程；常用复数指工事；食品营养强化']],'古城外的 walls and fortifications 是城墙与防御工事。food fortification 则是向食物添加营养成分，字面“增强”还在，但增加的不再是石墙。','military fortifications；food fortification；fortification with iron。','fortress 是防守地点；fortification 可说修筑防御的过程或具体工事，不只是一座城堡。',('Traces of the old fortifications remain around the town.','镇子周围还留着旧防御工事的痕迹。'),('The label explains the flour’s fortification with iron.','标签说明了面粉添加铁进行营养强化的情况。'),sources=['https://www.etymonline.com/word/fortification','https://en.wiktionary.org/wiki/fortification#English']),
E('fortified','英 /ˈfɔːtɪfaɪd/；美 /ˈfɔːrtəfaɪd/','加固的；设防的；添加营养素的；加强型的〔酒〕','原来的东西已经加进额外支撑或成分。','英语 fortify 的过去分词与形容词；y 在加 -ed 时变成 i。',FY+[['英语 fortify → fortified','被加强、加固；已添加营养素或蒸馏酒']],'a fortified town 是设防城镇；fortified cereal 是营养强化谷物；fortified wine 是加入蒸馏酒的加强型葡萄酒。三者共享增强画面，却不是同一种操作。','a fortified town；fortified foods；fortified wine。','fortifying 描述提供力量或正在强化；fortified 描述已经受到强化。酒的 fortified 不表示营养更丰富。',('The path leads to the gate of a fortified town.','小路通向一座设防城镇的大门。'),('The menu lists port under fortified wines.','菜单把波特酒列在加强型葡萄酒一栏。'),sources=['https://en.wiktionary.org/wiki/fortified#English','https://www.etymonline.com/word/fortify']),
E('fortissimo','英 /fɔːˈtɪsɪməʊ/；美 /fɔːrˈtɪsəmoʊ/','很强地；极强奏；极强段落〔音乐〕','乐谱要求把力度推到很强，但仍在乐句和音色的控制之内。','借意大利 fortissimo，是 forte“强”的最高级形式；-issimo 表示程度很高，forte 远接拉丁 fortis。',H+[['意大利 forte → fortissimo → 英语 fortissimo','强 → 很强；乐谱力度指示 ff']],'常写 ff，与 forte 的 f 对照。它规定力度，不规定速度，也不是一个固定分贝值；实际声音要跟作品、乐器和前后段落相配。也可作名词指很强的一段。','play fortissimo；a fortissimo passage；a sudden fortissimo。','forte 是强，fortissimo 是很强；pianissimo 则是很弱。不要把力度词理解成快慢指示。',('The orchestra entered fortissimo after a long silence.','长时间静默之后，乐队以极强力度进入。'),('The pianist kept the fortissimo passage clear rather than harsh.','钢琴家把极强段落弹得清晰，而不刺耳。'),sources=['https://www.merriam-webster.com/dictionary/fortissimo','https://dictionary.cambridge.org/dictionary/english/fortissimo'])
]
m=json.loads((BASE/'.cache/batch200/rewrite_spec.json').read_text());family=next(r['family'] for r in m['roots'] if r['id']=='C0446');owned=set(m['owned_words'])
EX={'forty':'常用的“四十”经古英语 fēowertiġ，属于 four + -ty 的数词来源，不属拉丁 fortis。Wiktionary 另列极罕见 fort + -y“堡垒似的”义，但无独立例证支撑，不据此把常见数词并入本族。'}
RROOT=[dict(id='C0446',meaning='强；使更强；用力；给予支持',core='把力量加上去：能防守、能推动，也能扶住一个人的心',image='fort 是守得住的地点；effort 是把力量拿出来用；comfort 是给人支持、使人安心；reinforce 则是在已有基础上再添一把力。',intro='拉丁 fortis 表示强壮、坚固、勇敢。经法语后，有的词保留 fort-，有的变成 force，有的音节弱化成 comfort、effort 里的形式。不要只把它记成肌肉力气：抵御压力的 fortitude、安慰人的 comfort，以及音乐力度 forte，都沿着“力量”展开。',forms='fort- 见 fort、fortify；force 接法语 force；effort 的 ef- 与更早 ex- 有关；comfort 接拉丁 confortare 与法语 conforter。forte 的长项义与音乐义分别经法语、意大利语借入。',branches=[['据点与增强','fort、fortress、fortify、fortification、fortified、fortifying、fortitude'],['用力与强制','force、forceful、forcible、forcibly、enforce、enforcement、reinforce、reinforcement'],['努力','effort、effortless、effortlessly'],['支持与舒适','comfort、comfortable、uncomfortable、comfortably、discomfort、comforting'],['强项与音乐力度','forte、fortissimo；pianoforte、piano 复用意大利强弱奏名称的词源讲解']],contrasts='forty“四十”走 four 的日耳曼数词支线。force 的地域瀑布义另接古诺斯语 fors。fortress 的 -ess 不是女性后缀。forceful 说有力，forcible 说强制；comfortable 说舒服，comforting 说能给人安慰。',practice='把同一个“增强”分别写成加固桥梁 reinforce、加固城镇 fortify、增强人的勇气 comfort。然后说明：一次表现可以看起来 effortless，却由多年的 effort 支撑。',words=[w for w in family if w not in EX],exclude=EX,sources=['https://www.etymonline.com/word/fort','https://www.etymonline.com/word/comfort','https://www.etymonline.com/word/effort','https://www.etymonline.com/word/forty'])]
assert {w['word'] for w in W}==(set(family)&owned)-set(EX), ((set(family)&owned)-set(EX))-{w['word'] for w in W}
for w in W:
 assert len(w['examples'])>=2 and len(w['history'])>=2 and w['ipa']
 assert all(len(n)==2 and all(isinstance(v,str) and v for v in n) for n in w['history'])
for k,d in [('roots',RROOT),('words',W)]: (OUT/f'{k}_batch200_spec_25_fort.json').write_text(json.dumps(d,ensure_ascii=False,indent=2))
